     &lt;li&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:georgia,serif"&gt;Triple Threat Mentoring&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:georgia,serif"&gt;Ujamaa Community Empowerment Network&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
